function firstSentence(t){t=String(t||'').trim();const m=t.match(/^(.+?[.!?])(?:\\s|$)/);return m?m[1]:t}
if(window.renderDailySpark){const f=window.renderDailySpark;window.renderDailySpark=function(){f();if(window.sparkHeadline)sparkHeadline.textContent=firstSentence(sparkHeadline.textContent)}}
